  (9372, '2026-11-02T20:33:19.651712+00:00', 'Hermes Terre D''Hermes Eau De Toilette Spray', '/assets/img/dropship/c9105225d6624a33db5a9d4d6027cba3.png', 'Hermes Terre D''Hermes Eau De Toilette Spray 50ml — премиальный оригинальный арабский парфюм со стойким шлейфом.', 'Al Majed for Oud', 33.18, '{"category":"Восточные","gender":"Унисекс","notesSummary":"Al Majed for Oud · Премиальный арабский парфюм","longevity":"10–14 часов","sillage":"Заметный, притягательный","volume":"100 мл EDP"}'::json),
  (4840, '2026-11-02T03:15:05.710745+00:00', 'Ajmal Chapter 5 - Eau De Parfum', '/assets/img/dropship/0b9db6add4d18023be072b3e0ff89ca3.png?v=6', 'Ajmal Ajmal Chapter 5 - Eau De Parfum — премиальный оригинальный арабский аромат (восточные пряные), созданный для ценителей утонченной восточной парфюмерии. Звучание раскрывается гармоничным букетом: Шафран · Черный перец · Кофе · Золотая амбра. Обладает великолепной стойкостью (10–14 часов (очень высокая)) и богатым, запоминающимся шлейфом. Подходит: для мужчин и женщин. Поставляется напрямую со складов сертифицированных дистрибьюторов в ОАЭ и Европе в оригинальном флаконе.', 'Ajmal', 51.63, '{"category":"Восточные пряные","categoryEn":"Oriental Spicy","categorySlug":"spicy","gender":"Унисекс","genderEn":"Unisex","longevity":"10–14 часов (очень высокая)","longevityEn":"10–14 hours (Very Long Lasting)","sillage":"Заметный, глубокий шлейф","sillageEn":"Deep, distinguished sillage","volume":"100 мл / 3.4 FL.OZ.","concentration":"Eau de Parfum","origin":"ОАЭ (Дубай)","originEn":"UAE (Dubai)","season":"Всесезонный","seasonEn":"All Seasons","notes":{"ru":{"top":["Королевский шафран","Черный перец","Кардамон"],"heart":["Корица","Кофейное зерно","Табак"],"base":["Золотая амбра","Бобы тонка","Сандал"]},"en":{"top":["Royal Saffron","Black Pepper","Cardamom"],"heart":["Cinnamon Bark","Roasted Coffee Bean","Tobacco"],"base":["Golden Amber","Tonka Bean","Sandalwood"]}},"notesSummary":"Шафран · Черный перец · Кофе · Золотая амбра","notesSummaryEn":"Saffron · Black Pepper · Coffee · Golden Amber","gtin":"6293708021178","inStock":true,"deliveryTime":"4–7 дней (прямая поставка из ОАЭ/ЕС)","deliveryTimeEn":"4–7 days (direct dispatch from UAE/EU)","updatedAt":"2026-11-02T03:15:03.886Z"}'::json),
  (5465, '2026-11-02T10:59:24.86954+00:00', 'Al Haramain Diamond Attar Perfume Oil Unisex Musk Saffron Rose Floral', '/assets/img/generated-products/23c1f5b2070712af8714c08cfb19d326fe3f03e3320dd13d911a80b98d5f2eb3.png', 'Al Haramain Diamond Attar Perfume Oil 12ml Unisex Musk Saffron Rose Floral — оригинальный премиальный парфюм бренда Al Haramain.', 'Al Haramain', 52.41, '{"gtin":"6291100131051","gender":"Унисекс","volume":"100 мл EDP","sillage":"Заметный, шлейфовый","category":"Цветочные","rawImage":"https://static.prod.qogita.com/files/images/variants/JSPz2284M4GuUZLTHp4rYP.jpg","longevity":"10–14 часов","notesSummary":"Шафран · Роза · Роза · Мускус","imageGeneration":{"status":"completed","attemptedOn":"2026-11-09","startedAt":"2026-11-09T17:57:00.327986+00:00","model":"@cf/black-forest-labs/flux-2-klein-4b","steps":4,"imageUrl":"/assets/img/generated-products/23c1f5b2070712af8714c08cfb19d326fe3f03e3320dd13d911a80b98d5f2eb3.png","width":1024,"height":1024,"completedAt":"2026-11-09T18:47:18.280317+00:00"},"imageGenerationAccountQuotas":{"primary":{"limitedAt":"2026-11-09T16:37:32.502406+00:00","partialAvailableAt":"2026-11-09T10:06:19.000Z","availableAt":"2026-11-10T16:37:32.502406+00:00","updatedAt":"2026-11-09T17:14:26.706661+00:00","lastUsedAt":"2026-11-09T16:37:29.067032+00:00"},"secondary":{"limitedAt":"2026-11-09T17:25:40.999458+00:00","availableAt":"2026-11-10T17:25:40.999458+00:00","updatedAt":"2026-11-09T17:25:40.999458+00:00","lastUsedAt":"2026-11-09T17:25:38.252920+00:00"},"third":{"limitedAt":"2026-11-09T17:52:30.784721+00:00","availableAt":"2026-11-10T17:52:30.784721+00:00","updatedAt":"2026-11-09T17:52:30.784721+00:00","lastUsedAt":"2026-11-09T17:52:28.602287+00:00"},"fourth":{"limitedAt":"2026-11-08T15:46:19.000Z","availableAt":"2026-11-09T15:46:19.000Z","updatedAt":"2026-11-09T17:57:07.026316+00:00","lastUsedAt":"2026-11-09T17:57:07.026316+00:00"},"fifth":{"limitedAt":"2026-11-08T16:07:14.000Z","availableAt":"2026-11-09T16:07:14.000Z","updatedAt":"2026-11-08T16:07:14.000Z"}},"variantFid":"L8R37Z","notes":{"ru":{"top":["Шафран","Роза","Бергамот","Мускатный Орех"],"heart":["Роза","Жасмин","Герань","Корица"],"base":["Мускус","Амбра","Сандал","Ваниль","Уд"]},"en":{"top":["Saffron","Rose","Bergamot","Nutmeg"],"heart":["Rose","Jasmine","Geranium","Cinnamon"],"base":["Musk","Amber","Sandalwood","Vanilla","Oud"]}},"notesVerified":true,"notesSource":"deepseek","notesLookup":{"status":"found","source":"deepseek","checkedAt":"2026-11-11T20:45:41.701Z","model":"deepseek-chat","generated":true},"notesSummaryEn":"Saffron · Rose · Rose · Musk","descriptionRu":"Al Haramain Diamond Attar — это изысканное восточно-цветочное масло, сочетающее яркую пряную динамику и бархатистую цветочную глубину с мягким древесным шлейфом. Аромат выстраивает гармоничный баланс между теплыми и свежими гранями, создавая сбалонированное и элегантное звучание. Композиция открывается бодрящим цитрусовым всплеском бергамота, который мгновенно смягчается благородной терпкостью шафрана, благоуханием розы и деликатным теплом мускатного ореха. Постепенно раскрываясь, аромат обретает пышный сердечный аккорд, где доминирует богатый дуэт розы и жасмина, дополненный травянистой свежестью герани и пикантным акцентом корицы. В базе аромат приобретает обволакивающую глубину благодаря классическому сочетанию мускуса и амбры, соединенному с кремовым сандалом, сладковатой ванилью и благородными древесными нюансами уда. Этот гармоничный финал оставляет на коже долговечный, мягкий и теплый след.","descriptionEn":"Al Haramain Diamond Attar is a refined oriental-floral attar that unites vibrant spicy dynamics and velvety floral depth with a soft woody trail. The fragrance builds a harmonious balance between warm and fresh facets, creating a poised and elegant profile. The composition opens with a refreshing burst of bergamot citrus, which is promptly softened by the noble bitterness of saffron, the fragrance of rose, and the delicate warmth of nutmeg. Unfolding gradually, the scent reveals a lush heart accord dominated by a rich duet of rose and jasmine, complemented by the herbal freshness of geranium and a piquant touch of cinnamon. In the base, the fragrance acquires an enveloping depth through a classic combination of musk and amber, blended with creamy sandalwood, sweet vanilla, and noble woody nuances of oud. This harmonious finale leaves a long-lasting, soft, and warm trace on the skin.","descriptionSource":"gemini","descriptionsLookup":{"source":"gemini","model":"gemini-3.5-flash-lite","checkedAt":"2026-11-13T20:32:43.920Z"}}'::json),
  (6240, '2026-11-02T10:59:27.115244+00:00', 'Armaf Odyssey Eau De Montagne Deodorant Spray - Amber Vanilla', '/assets/img/generated-products/ea04a4ac3a44b1e86e7e19e210598d261ca89cccc32a7a1c3e3515f74f8c6943.png', 'Armaf Odyssey Eau De Montagne Deodorant Spray 200ml - Amber Vanilla — оригинальный премиальный парфюм бренда Armaf.', 'Armaf', 2.02, '{"category":"Гурманские","gender":"Унисекс","notesSummary":"Бергамот · Розовый Перец · Лаванда · Амбра","longevity":"10–14 часов","sillage":"Заметный, шлейфовый","volume":"100 мл EDP","rawImage":"https://static.prod.qogita.com/files/images/variants/cNdWStsDtCB4QERxYz48q7.jpg","gtin":"6295199813904","imageGeneration":{"status":"completed","attemptedOn":"2026-11-10","startedAt":"2026-11-10T20:11:08.852479+00:00","model":"@cf/black-forest-labs/flux-2-klein-4b","steps":4,"imageUrl":"/assets/img/generated-products/ea04a4ac3a44b1e86e7e19e210598d261ca89cccc32a7a1c3e3515f74f8c6943.png","width":1024,"height":1024,"completedAt":"2026-11-10T20:16:58.932495+00:00"},"imageGenerationAccountQuotas":{"primary":{"limitedAt":"2026-11-10T18:31:45.901098+00:00","partialAvailableAt":"2026-11-09T10:06:19.000Z","availableAt":"2026-11-11T18:31:45.901098+00:00","updatedAt":"2026-11-10T18:31:45.901098+00:00","lastUsedAt":"2026-11-10T18:31:43.067137+00:00"},"secondary":{"limitedAt":"2026-11-10T19:01:38.534481+00:00","availableAt":"2026-11-11T19:01:38.534481+00:00","updatedAt":"2026-11-10T19:01:38.534481+00:00","lastUsedAt":"2026-11-10T19:01:24.924755+00:00"},"third":{"limitedAt":"2026-11-10T19:32:13.941529+00:00","availableAt":"2026-11-11T19:32:13.941529+00:00","updatedAt":"2026-11-10T19:32:13.941529+00:00","lastUsedAt":"2026-11-10T19:32:10.736028+00:00"},"fourth":{"limitedAt":"2026-11-09T18:16:27.645979+00:00","availableAt":"2026-11-10T18:16:27.645979+00:00","updatedAt":"2026-11-10T20:11:14.376563+00:00","lastUsedAt":"2026-11-10T20:11:14.376563+00:00"},"fifth":{"limitedAt":"2026-11-09T18:40:25.593266+00:00","availableAt":"2026-11-10T18:40:25.593266+0