  (5510, '2026-11-02T10:59:24.997288+00:00', 'Al Haramain Royal Rose Eau De Parfum', '/assets/img/generated-products/74ed89c380e47bdf5b1447a4dca4a0c592b99d61a77ecf69d5230dead62d00ec.png', 'Al Haramain Royal Rose Eau De Parfum 100ml — оригинальный премиальный парфюм бренда Al Haramain.', 'Al Haramain', 47.65, '{"gtin":"6600001258321","gender":"Унисекс","volume":"100 мл EDP","sillage":"Заметный, шлейфовый","category":"Цветочные","rawImage":"https://static.prod.qogita.com/files/images/variants/AiSfmDcqDfSLHUhy2Mt5E9.jpg","longevity":"10–14 часов","notesSummary":"Роза · Бергамот · Роза · Мускус","imageGeneration":{"status":"completed","attemptedOn":"2026-11-09","startedAt":"2026-11-09T18:03:32.991060+00:00","model":"@cf/black-forest-labs/flux-2-klein-4b","steps":4,"imageUrl":"/assets/img/generated-products/74ed89c380e47bdf5b1447a4dca4a0c592b99d61a77ecf69d5230dead62d00ec.png","width":1024,"height":1024,"completedAt":"2026-11-09T18:47:35.587579+00:00"},"imageGenerationAccountQuotas":{"primary":{"limitedAt":"2026-11-09T16:37:32.502406+00:00","partialAvailableAt":"2026-11-09T10:06:19.000Z","availableAt":"2026-11-10T16:37:32.502406+00:00","updatedAt":"2026-11-09T17:14:26.706661+00:00","lastUsedAt":"2026-11-09T16:37:29.067032+00:00"},"secondary":{"limitedAt":"2026-11-09T17:25:40.999458+00:00","availableAt":"2026-11-10T17:25:40.999458+00:00","updatedAt":"2026-11-09T17:25:40.999458+00:00","lastUsedAt":"2026-11-09T17:25:38.252920+00:00"},"third":{"limitedAt":"2026-11-09T17:52:30.784721+00:00","availableAt":"2026-11-10T17:52:30.784721+00:00","updatedAt":"2026-11-09T17:52:30.784721+00:00","lastUsedAt":"2026-11-09T17:52:28.602287+00:00"},"fourth":{"limitedAt":"2026-11-08T15:46:19.000Z","availableAt":"2026-11-09T15:46:19.000Z","updatedAt":"2026-11-09T18:03:38.168069+00:00","lastUsedAt":"2026-11-09T18:03:38.168069+00:00"},"fifth":{"limitedAt":"2026-11-08T16:07:14.000Z","availableAt":"2026-11-09T16:07:14.000Z","updatedAt":"2026-11-08T16:07:14.000Z"}},"variantFid":"4s9nWeJeEy","notes":{"ru":{"top":["Роза","Бергамот","Лимон","Шафран"],"heart":["Роза","Герань","Жасмин","Пион"],"base":["Мускус","Амбра","Сандал","Ваниль"]},"en":{"top":["Rose","Bergamot","Lemon","Saffron"],"heart":["Rose","Geranium","Jasmine","Peony"],"base":["Musk","Amber","Sandalwood","Vanilla"]}},"notesVerified":true,"notesSource":"deepseek","notesLookup":{"status":"found","source":"deepseek","checkedAt":"2026-11-11T20:45:49.135Z","model":"deepseek-chat","generated":true},"notesSummaryEn":"Rose · Bergamot · Rose · Musk","descriptionRu":"Al Haramain Royal Rose — это утонченная цветочная композиция, в которой классическая грация дамасской розы встречается с искристой свежестью цитрусовых и пряным теплом шафрана. Аромат балансирует между прохладной грациозностью лепестков и глубоким, обволакивающим шлейфом. Вступительные аккорды встречают ярким дуэтом бергамота и лимона, чья цитрусовая энергия мягко приглушается благородной горечью шафрана и деликатным розовым нюансом. Постепенно композиция раскрывается пышным цветочным букетом: к доминирующей розе присоединяются травянистые оттенки герани, сладость жасмина и воздушная нежность пиона, создавая ощущение прогулки по цветущему саду. Завершающий шлейф обретает чувственность благодаря сочетанию теплой амбры и сливочного сандала. Мягкие ноты ванили и чистого мускуса придают аромату завершенность, оставляя на коже стойкий, бархатистый след.","descriptionEn":"Al Haramain Royal Rose is a refined floral composition where the classic grace of rose meets the sparkling freshness of citrus and the spicy warmth of saffron. The fragrance strikes a perfect balance between the cool elegance of petals and a deep, enveloping trail. The opening chords introduce a vibrant duet of bergamot and lemon, whose citrus energy is softly tempered by the noble bitterness of saffron and a delicate hint of rose. Gradually, the composition unfolds into a lush floral bouquet: the dominant rose is joined by the herbal nuances of geranium, the sweetness of jasmine, and the airy tenderness of peony, evoking the sensation of a walk through a blooming garden. The final trail gains sensuality through a blend of warm amber and creamy sandalwood. Soft notes of vanilla and clean musk provide a smooth finish, leaving a persistent, velvety impression on the skin.","descriptionSource":"gemini","descriptionsLookup":{"source":"gemini","model":"gemini-3.1-flash-lite","checkedAt":"2026-11-13T20:34:14.047Z"}}'::json),
  (4853, '2026-11-02T03:15:06.460277+00:00', 'Amouage Line 618 Essence de Parfum - Unisex Fragrance', '/assets/img/dropship/5723289955650c93f5e807688e922c6d.png?v=6', 'Amouage Amouage Line 618 Essence de Parfum 100ml - Unisex Fragrance — премиальный оригинальный арабский аромат (восточные пряные), созданный для ценителей утонченной восточной парфюмерии. Звучание раскрывается гармоничным букетом: Шафран · Черный перец · Кофе · Золотая амбра. Обладает великолепной стойкостью (10–14 часов (очень высокая)) и богатым, запоминающимся шлейфом. Подходит: для мужчин и женщин. Поставляется напрямую со складов сертифицированных дистрибьюторов в ОАЭ и Европе в оригинальном флаконе.', 'Amouage', 336.98, '{"category":"Восточные пряные","categoryEn":"Oriental Spicy","categorySlug":"spicy","gender":"Унисекс","genderEn":"Unisex","longevity":"10–14 часов (очень высокая)","longevityEn":"10–14 hours (Very Long Lasting)","sillage":"Заметный, глубокий шлейф","sillageEn":"Deep, distinguished sillage","volume":"100 мл / 3.4 FL.OZ.","concentration":"Eau de Parfum","origin":"Оман","originEn":"Oman","season":"Всесезонный","seasonEn":"All Seasons","notes":{"ru":{"top":["Королевский шафран","Черный перец","Кардамон"],"heart":["Корица","Кофейное зерно","Табак"],"base":["Золотая амбра","Бобы тонка","Сандал"]},"en":{"top":["Royal Saffron","Black Pepper","Cardamom"],"heart":["Cinnamon Bark","Roasted Coffee Bean","Tobacco"],"base":["Golden Amber","Tonka Bean","Sandalwood"]}},"notesSummary":"Шафран · Черный перец · Кофе · Золотая амбра","notesSummaryEn":"Saffron · Black Pepper · Coffee · Golden Amber","gtin":"0701666411253","inStock":true,"deliveryTime":"4–7 дней (прямая поставка из ОАЭ/ЕС)","deliveryTimeEn":"4–7 days (direct dispatch from UAE/EU)","updatedAt":"2026-11-02T03:15:03.887Z"}'::json),
