  (5073, '2026-11-02T10:59:23.718524+00:00', 'Ajmal Entice Pour Femme Eau De Parfum', '/assets/img/generated-products/b6339de759e8d0edc1dd9ace7b3712c450ac6e4390dd84de1208646cd2db4588.png', 'Ajmal Entice Pour Femme Eau De Parfum — оригинальный премиальный парфюм бренда Ajmal.', 'Ajmal', 14.58, '{"gtin":"6293708004065","gender":"Женский","volume":"100 мл EDP","sillage":"Заметный, шлейфовый","category":"Свежие","rawImage":"https://static.prod.qogita.com/files/images/variants/9rjyUvi2uxPFM4ciNkyA2T.jpg","longevity":"10–14 часов","notesSummary":"Бергамот · Розовый Перец · Роза · Мускус","imageGeneration":{"status":"completed","attemptedOn":"2026-11-09","startedAt":"2026-11-09T17:15:26.915364+00:00","model":"@cf/black-forest-labs/flux-2-klein-4b","steps":4,"imageUrl":"/assets/img/generated-products/b6339de759e8d0edc1dd9ace7b3712c450ac6e4390dd84de1208646cd2db4588.png","width":1024,"height":1024,"completedAt":"2026-11-09T18:45:43.170469+00:00"},"retiredGeneratedImages":["/assets/img/generated-products/947edd81adeab666b657501d78e5ca0d126dc6b26bf318cdcb15dd879f95098c.png"],"imageGenerationAccountQuotas":{"primary":{"limitedAt":"2026-11-09T16:37:32.502406+00:00","partialAvailableAt":"2026-11-09T10:06:19.000Z","availableAt":"2026-11-10T16:37:32.502406+00:00","updatedAt":"2026-11-09T17:14:26.706661+00:00","lastUsedAt":"2026-11-09T16:37:29.067032+00:00"},"secondary":{"limitedAt":"2026-11-08T14:53:00.000Z","availableAt":"2026-11-09T14:53:00.000Z","updatedAt":"2026-11-09T17:15:33.118778+00:00","lastUsedAt":"2026-11-09T17:15:33.118778+00:00"},"third":{"limitedAt":"2026-11-08T15:25:17.000Z","availableAt":"2026-11-09T15:25:17.000Z","updatedAt":"2026-11-08T15:25:17.000Z"},"fourth":{"limitedAt":"2026-11-08T15:46:19.000Z","availableAt":"2026-11-09T15:46:19.000Z","updatedAt":"2026-11-08T15:46:19.000Z"},"fifth":{"limitedAt":"2026-11-08T16:07:14.000Z","availableAt":"2026-11-09T16:07:14.000Z","updatedAt":"2026-11-08T16:07:14.000Z"}},"variantFid":"3tF3ndX9gB","notes":{"ru":{"top":["Бергамот","Розовый Перец","Личи","Мандарин"],"heart":["Роза","Жасмин","Пион","Фрезия"],"base":["Мускус","Ваниль","Сандал","Амбра","Кедр"]},"en":{"top":["Bergamot","Pink Pepper","Litchi","Mandarin Orange"],"heart":["Rose","Jasmine","Peony","Freesia"],"base":["Musk","Vanilla","Sandalwood","Amber","Cedar"]}},"notesVerified":true,"notesSource":"deepseek","notesLookup":{"status":"found","source":"deepseek","checkedAt":"2026-11-11T20:44:18.069Z","model":"deepseek-chat","generated":true},"notesSummaryEn":"Bergamot · Pink Pepper · Rose · Musk","descriptionRu":"Ajmal Entice Pour Femme — это композиция, построенная на контрасте искрящейся цитрусовой свежести и глубокого цветочного очарования. Аромат раскрывается энергичным сочетанием бергамота и мандарина, дополненным пикантными искрами розового перца и экзотическими оттенками личи. В сердце аромата расцветает нежный букет из розы, жасмина, пиона и фрезии, создавая утонченную женственную ауру. Завершается звучание мягким шлейфом из мускуса, ванили и сандала, которые в сочетании с нотами амбры и кедра придают композиции теплоту и благородную стойкость.","descriptionEn":"Ajmal Entice Pour Femme is a fragrance defined by the contrast between sparkling citrus brightness and a refined floral core. The opening captures the senses with a vibrant blend of bergamot and mandarin, sharpened by the spicy snap of pink pepper and the succulent sweetness of litchi. The heart blossoms into a sophisticated bouquet of rose, jasmine, peony, and freesia, lending the fragrance its airy and graceful character. A soft, lingering trail of musk, vanilla, and sandalwood settles against a grounding base of amber and cedar, providing warmth and depth to the final impression.","descriptionSource":"gemini","descriptionsLookup":{"source":"gemini","model":"gemini-3.1-flash-lite","checkedAt":"2026-11-13T19:32:49.158Z"}}'::json),
  (4333, '2026-11-01T21:27:42.41853+00:00', 'French Avenue Ravine Ice Eau De Parfum Unisex', '/assets/img/dropship/9c7a4ea5823de02392612df6d989d3f1.png?v=8', 'French Avenue French Avenue Ravine Ice Eau De Parfum Unisex 100 Ml — премиальный оригинальный арабский аромат (свежие акватические), созданный для ценителей утонченной восточной парфюмерии. Звучание раскрывается гармоничным букетом: Морской бриз · Бергамот · Мята · Амброксан. Обладает великолепной стойкостью (8–11 часов (стойкая свежесть)) и богатым, запоминающимся шлейфом. Подходит: для мужчин и женщин. Поставляется напрямую со складов сертифицированных дистрибьюторов в ОАЭ и Европе в оригинальном флаконе.', 'French Avenue', 19.35, '{"category":"Свежие акватические","categoryEn":"Fresh Aquatic","categorySlug":"fresh","gender":"Унисекс","genderEn":"Unisex","longevity":"8–11 часов (стойкая свежесть)","longevityEn":"8–11 hours (Long-lasting Freshness)","sillage":"Освежающий, диффузный шлейф","sillageEn":"Refreshing, diffusive sillage","volume":"100 мл / 3.4 FL.OZ.","concentration":"Eau de Parfum","origin":"ОАЭ (Дубай)","originEn":"UAE (Dubai)","season":"Весна / Лето","seasonEn":"Spring / Summer","gtin":"6298042001909","inStock":true,"deliveryTime":"4–7 дней (прямая поставка из ОАЭ/ЕС)","deliveryTimeEn":"4–7 days (direct dispatch from UAE/EU)","updatedAt":"2026-11-01T21:27:38.025Z","minOrderQuantity":4,"unit":4,"notesVerified":false}'::json),
