  (5117, '2026-11-02T10:59:23.880825+00:00', 'Ajmal Rose Wood Eau De Parfum', '/assets/img/generated-products/46c645ea9fce23b388c326ab6ace569101fc1e0b45c5aeb4ebbfca3c5c108510.png', 'Ajmal Rose Wood Eau De Parfum — оригинальный премиальный парфюм бренда Ajmal.', 'Ajmal', 49.05, '{"gtin":"6293708007776","gender":"Унисекс","volume":"100 мл EDP","sillage":"Заметный, шлейфовый","category":"Цветочные","rawImage":"https://static.prod.qogita.com/files/images/variants/Jh6QisNCuXtw5WwVF4U8ZL.jpg","longevity":"10–14 часов","notesSummary":"Бергамот · Лимон · Роза · Сандаловое Дерево","imageGeneration":{"status":"completed","attemptedOn":"2026-11-09","startedAt":"2026-11-09T16:25:35.781143+00:00","model":"@cf/black-forest-labs/flux-2-klein-4b","steps":4,"imageUrl":"/assets/img/generated-products/46c645ea9fce23b388c326ab6ace569101fc1e0b45c5aeb4ebbfca3c5c108510.png","width":1024,"height":1024,"completedAt":"2026-11-09T16:49:24.873531+00:00"},"retiredGeneratedImages":["/assets/img/generated-products/ed9fab4f2c7a0d1806e3af3af73fb2059ca8033dac522672ce3d0577bda9c3c7.png"],"imageGenerationAccountQuotas":{"primary":{"limitedAt":"2026-11-08T14:38:00.000Z","availableAt":"2026-11-09T14:38:00.000Z","updatedAt":"2026-11-09T16:25:47.228473+00:00","lastUsedAt":"2026-11-09T16:25:47.228473+00:00"},"secondary":{"limitedAt":"2026-11-08T14:53:00.000Z","availableAt":"2026-11-09T14:53:00.000Z","updatedAt":"2026-11-08T14:53:00.000Z"},"third":{"limitedAt":"2026-11-08T15:25:17.000Z","availableAt":"2026-11-09T15:25:17.000Z","updatedAt":"2026-11-08T15:25:17.000Z"},"fourth":{"limitedAt":"2026-11-08T15:46:19.000Z","availableAt":"2026-11-09T15:46:19.000Z","updatedAt":"2026-11-08T15:46:19.000Z"},"fifth":{"limitedAt":"2026-11-08T16:07:14.000Z","availableAt":"2026-11-09T16:07:14.000Z","updatedAt":"2026-11-08T16:07:14.000Z"}},"variantFid":"Dc82eRiue9","notes":{"ru":{"top":["Бергамот","Лимон","Розовый Перец","Кардамон"],"heart":["Роза","Герань","Жасмин","Фиалка"],"base":["Сандаловое Дерево","Кедровое Дерево","Мускус","Амбра","Ваниль"]},"en":{"top":["Bergamot","Lemon","Pink Pepper","Cardamom"],"heart":["Rose","Geranium","Jasmine","Violet"],"base":["Sandalwood","Cedarwood","Musk","Amber","Vanilla"]}},"notesVerified":true,"notesSource":"deepseek","notesLookup":{"status":"found","source":"deepseek","checkedAt":"2026-11-11T20:44:31.846Z","model":"deepseek-chat","generated":true},"notesSummaryEn":"Bergamot · Lemon · Rose · Sandalwood","descriptionRu":"Ajmal Rose Wood — это утонченная композиция, в которой классическая цветочная элегантность встречается с пряным древесным характером. Аромат выстраивает изысканный контраст между легкой цитрусовой искрой и глубоким, обволакивающим теплом базовых нот. Вступительные аккорды бергамота и лимона мгновенно наполняют пространство свежестью, которую подчеркивают пикантные нюансы розового перца и кардамона. Постепенно композиция раскрывается пышным цветочным букетом, где бархатистая роза переплетается с травянистыми оттенками герани, нежностью жасмина и пудровыми полутонами фиалки. Завершающий шлейф обретает глубину благодаря сочетанию сливочного сандала и строгого кедра. Теплые акценты амбры и ванили в союзе с мягким мускусом придают композиции стойкое, чувственное звучание, оставляя после себя благородный и запоминающийся след.","descriptionEn":"Ajmal Rose Wood is a sophisticated composition where classic floral elegance meets a spicy, woody character. The fragrance creates a refined contrast between an effervescent citrus sparkle and the deep, enveloping warmth of its base notes. The opening chords of bergamot and lemon immediately infuse the air with freshness, sharpened by the piquant nuances of pink pepper and cardamom. Gradually, the composition unfolds into a lush floral bouquet, where velvety rose intertwines with the herbaceous facets of geranium, the delicacy of jasmine, and the powdery undertones of violet. The final trail gains depth through a blend of creamy sandalwood and structured cedarwood. Warm accents of amber and vanilla, unified with soft musk, provide the fragrance with a lasting, sensual character, leaving behind a noble and memorable impression.","descriptionSource":"gemini","descriptionsLookup":{"source":"gemini","model":"gemini-3.1-flash-lite","checkedAt":"2026-11-13T19:36:42.780Z"}}'::json),
