  (5504, '2026-11-02T10:59:24.997288+00:00', 'Al Haramain Ajwa Perfume Oil', '/assets/img/generated-products/ef2da6757e5238cd81968cbbf5804c9c542fe5a188cc3d07eb735931aaf1556c.png', 'Al Haramain Ajwa Perfume Oil — оригинальный премиальный парфюм бренда Al Haramain.', 'Al Haramain', 36.46, '{"gtin":"6291100132324","gender":"Унисекс","volume":"100 мл EDP","sillage":"Заметный, шлейфовый","category":"Восточные","rawImage":"https://static.prod.qogita.com/files/images/variants/TWsx8PZPaTSKvGQWSokahE.jpg","longevity":"10–14 часов","notesSummary":"Шафран · Бергамот · Роза · Амбра","imageGeneration":{"status":"completed","attemptedOn":"2026-11-09","startedAt":"2026-11-09T18:02:49.045848+00:00","model":"@cf/black-forest-labs/flux-2-klein-4b","steps":4,"imageUrl":"/assets/img/generated-products/ef2da6757e5238cd81968cbbf5804c9c542fe5a188cc3d07eb735931aaf1556c.png","width":1024,"height":1024,"completedAt":"2026-11-09T18:47:33.297277+00:00"},"imageGenerationAccountQuotas":{"primary":{"limitedAt":"2026-11-09T16:37:32.502406+00:00","partialAvailableAt":"2026-11-09T10:06:19.000Z","availableAt":"2026-11-10T16:37:32.502406+00:00","updatedAt":"2026-11-09T17:14:26.706661+00:00","lastUsedAt":"2026-11-09T16:37:29.067032+00:00"},"secondary":{"limitedAt":"2026-11-09T17:25:40.999458+00:00","availableAt":"2026-11-10T17:25:40.999458+00:00","updatedAt":"2026-11-09T17:25:40.999458+00:00","lastUsedAt":"2026-11-09T17:25:38.252920+00:00"},"third":{"limitedAt":"2026-11-09T17:52:30.784721+00:00","availableAt":"2026-11-10T17:52:30.784721+00:00","updatedAt":"2026-11-09T17:52:30.784721+00:00","lastUsedAt":"2026-11-09T17:52:28.602287+00:00"},"fourth":{"limitedAt":"2026-11-08T15:46:19.000Z","availableAt":"2026-11-09T15:46:19.000Z","updatedAt":"2026-11-09T18:02:55.342310+00:00","lastUsedAt":"2026-11-09T18:02:55.342310+00:00"},"fifth":{"limitedAt":"2026-11-08T16:07:14.000Z","availableAt":"2026-11-09T16:07:14.000Z","updatedAt":"2026-11-08T16:07:14.000Z"}},"variantFid":"2RXVE3","notes":{"ru":{"top":["Шафран","Бергамот","Кардамон","Розовый Перец"],"heart":["Роза","Жасмин","Уд","Корица"],"base":["Амбра","Мускус","Сандал","Ваниль","Пачули"]},"en":{"top":["Saffron","Bergamot","Cardamom","Pink Pepper"],"heart":["Rose","Jasmine","Oud","Cinnamon"],"base":["Amber","Musk","Sandalwood","Vanilla","Patchouli"]}},"notesVerified":true,"notesSource":"deepseek","notesLookup":{"status":"found","source":"deepseek","checkedAt":"2026-11-11T20:45:48.500Z","model":"deepseek-chat","generated":true},"notesSummaryEn":"Saffron · Bergamot · Rose · Amber","descriptionRu":"Al Haramain Ajwa — это восточная композиция, построенная на изысканном контрасте между искристой цитрусовой свежестью и глубоким, пряным теплом. Аромат раскрывается энергичным сочетанием бергамота, шафрана, кардамона и розового перца, создавая яркое, пряно-цитрусовое вступление. В сердце композиции расцветает бархатистый дуэт розы и жасмина, чья цветочная мягкость подчеркнута пикантными акцентами корицы и благородным, дымным звучанием уда. Это гармоничное развитие постепенно переходит в насыщенный шлейф. Базовые ноты амбры, ванили и сандала придают аромату сливочную сладость, в то время как пачули и мускус добавляют глубину и стойкое древесно-землистое послевкусие, завершающее этот многогранный восточный образ.","descriptionEn":"Al Haramain Ajwa is an Oriental composition defined by the sophisticated contrast between sparkling citrus freshness and deep, spicy warmth. The fragrance opens with an energetic blend of bergamot, saffron, cardamom, and pink pepper, creating a vibrant, zesty introduction. At the heart, a velvety duo of rose and jasmine unfolds, its floral softness underscored by piquant accents of cinnamon and the noble, smoky character of oud. This harmonious development serves as a bridge toward a richer, more resonant base. The dry down features a base of amber, vanilla, and sandalwood, which impart a creamy sweetness to the skin. Patchouli and musk provide depth and a lingering, earthy-woody trail, completing this multifaceted Oriental profile.","descriptionSource":"gemini","descriptionsLookup":{"source":"gemini","model":"gemini-3.1-flash-lite-preview","checkedAt":"2026-11-13T20:34:04.831Z"}}'::json),
