  (5550, '2026-11-02T10:59:25.149382+00:00', 'Al Haramain Signature Pour Homme Eau De Toilette with Lily Amber Wood', '/assets/img/generated-products/f0ad909601fcfb2b9c5efc4b5d97c5aa424591b24dec78a358bf85e216f399d3.png', 'Al Haramain Signature Pour Homme Eau De Toilette with Lily Amber Wood 100ml — оригинальный премиальный парфюм бренда Al Haramain.', 'Al Haramain', 17.09, '{"category":"Древесные","gender":"Мужской","notesSummary":"Бергамот · Лимон · Ландыш · Амбра","longevity":"10–14 часов","sillage":"Заметный, шлейфовый","volume":"100 мл EDP","rawImage":"https://static.prod.qogita.com/files/images/variants/LTnAd6JbDSqsCu9ei3RLjn.jpg","gtin":"6600001265107","imageGeneration":{"status":"completed","attemptedOn":"2026-11-09","startedAt":"2026-11-09T18:11:02.450804+00:00","model":"@cf/black-forest-labs/flux-2-klein-4b","steps":4,"imageUrl":"/assets/img/generated-products/f0ad909601fcfb2b9c5efc4b5d97c5aa424591b24dec78a358bf85e216f399d3.png","width":1024,"height":1024,"completedAt":"2026-11-09T18:47:55.103735+00:00"},"imageGenerationAccountQuotas":{"primary":{"limitedAt":"2026-11-09T16:37:32.502406+00:00","partialAvailableAt":"2026-11-09T10:06:19.000Z","availableAt":"2026-11-10T16:37:32.502406+00:00","updatedAt":"2026-11-09T17:14:26.706661+00:00","lastUsedAt":"2026-11-09T16:37:29.067032+00:00"},"secondary":{"limitedAt":"2026-11-09T17:25:40.999458+00:00","availableAt":"2026-11-10T17:25:40.999458+00:00","updatedAt":"2026-11-09T17:25:40.999458+00:00","lastUsedAt":"2026-11-09T17:25:38.252920+00:00"},"third":{"limitedAt":"2026-11-09T17:52:30.784721+00:00","availableAt":"2026-11-10T17:52:30.784721+00:00","updatedAt":"2026-11-09T17:52:30.784721+00:00","lastUsedAt":"2026-11-09T17:52:28.602287+00:00"},"fourth":{"limitedAt":"2026-11-08T15:46:19.000Z","availableAt":"2026-11-09T15:46:19.000Z","updatedAt":"2026-11-09T18:11:18.071275+00:00","lastUsedAt":"2026-11-09T18:11:18.071275+00:00"},"fifth":{"limitedAt":"2026-11-08T16:07:14.000Z","availableAt":"2026-11-09T16:07:14.000Z","updatedAt":"2026-11-08T16:07:14.000Z"}},"variantFid":"63Z5PW","notes":{"ru":{"top":["Бергамот","Лимон","Розовый Перец","Лаванда"],"heart":["Ландыш","Жасмин","Герань","Амбра"],"base":["Амбра","Древесные Ноты","Мускус","Ваниль","Пачули"]},"en":{"top":["Bergamot","Lemon","Pink Pepper","Lavender"],"heart":["Lily of the Valley","Jasmine","Geranium","Amber"],"base":["Amber","Woody Notes","Musk","Vanilla","Patchouli"]}},"notesVerified":true,"notesSource":"deepseek","notesLookup":{"status":"found","source":"deepseek","checkedAt":"2026-11-11T20:45:58.795Z","model":"deepseek-chat","generated":true},"notesSummaryEn":"Bergamot · Lemon · Lily of the Valley · Amber","descriptionRu":"Al Haramain Signature Pour Homme — это выразительная древесная композиция, построенная на контрасте между искристой цитрусовой свежестью и глубоким, обволакивающим теплом. Аромат открывается энергичным всплеском бергамота и лимона, чью остроту подчеркивает пикантный розовый перец и прохладный оттенок лаванды. В сердце раскрывается изысканный цветочный букет из ландыша, жасмина и герани, который плавно перетекает в насыщенное амбровое звучание. Это сочетание придает композиции утонченную элегантность и характерную глубину. Базовый аккорд объединяет богатство древесных нот с мягким мускусным шлейфом. Сладость ванили и землистые нюансы пачули завершают звучание, создавая стойкий и гармоничный древесный финал.","descriptionEn":"Al Haramain Signature Pour Homme is a distinct woody composition defined by the contrast between sparkling citrus brightness and deep, enveloping warmth. The fragrance opens with an energetic splash of bergamot and lemon, sharpened by the piquant touch of pink pepper and the cool, herbal clarity of lavender. At the heart, a refined floral bouquet of lily of the valley, jasmine, and geranium unfolds, seamlessly transitioning into a rich, resonant amber core. This interplay lends the scent an air of sophisticated elegance and notable depth. The base anchors the fragrance with an array of woody notes layered against a soft, lingering musky trail. Subtle hints of vanilla and the earthy resonance of patchouli complete the profile, leaving a balanced and enduring woody impression.","descriptionSource":"gemini","descriptionsLookup":{"source":"gemini","model":"gemini-3.1-flash-lite","checkedAt":"2026-11-13T20:36:31.581Z"}}'::json),
