  (5699, '2026-11-02T10:59:25.547405+00:00', 'Ard al Zaafaran Dirham Eau de Parfum - Fresh Floral Citrus Scent', '/assets/img/generated-products/2544df8ee69cd6b93c1cc2cb2781d99af8c25e3efe17777c72b575783b014cbb.png', 'Ard al Zaafaran Dirham Eau de Parfum 100ml - Fresh Floral Citrus Scent — оригинальный премиальный парфюм бренда Ard Al Zaafaran.', 'Ard Al Zaafaran', 8.18, '{"category":"Свежие","gender":"Унисекс","notesSummary":"Бергамот · Лимон · Жасмин · Белый Мускус","longevity":"10–14 часов","sillage":"Заметный, шлейфовый","volume":"100 мл EDP","rawImage":"https://static.prod.qogita.com/files/images/variants/RkE7RHxGnkAwLz7usm8rXx.jpg","gtin":"6295199795231","imageGeneration":{"status":"completed","attemptedOn":"2026-11-09","startedAt":"2026-11-09T18:27:29.216257+00:00","model":"@cf/black-forest-labs/flux-2-klein-4b","steps":4,"imageUrl":"/assets/img/generated-products/2544df8ee69cd6b93c1cc2cb2781d99af8c25e3efe17777c72b575783b014cbb.png","width":1024,"height":1024,"completedAt":"2026-11-09T18:48:37.746019+00:00"},"imageGenerationAccountQuotas":{"primary":{"limitedAt":"2026-11-09T16:37:32.502406+00:00","partialAvailableAt":"2026-11-09T10:06:19.000Z","availableAt":"2026-11-10T16:37:32.502406+00:00","updatedAt":"2026-11-09T17:14:26.706661+00:00","lastUsedAt":"2026-11-09T16:37:29.067032+00:00"},"secondary":{"limitedAt":"2026-11-09T17:25:40.999458+00:00","availableAt":"2026-11-10T17:25:40.999458+00:00","updatedAt":"2026-11-09T17:25:40.999458+00:00","lastUsedAt":"2026-11-09T17:25:38.252920+00:00"},"third":{"limitedAt":"2026-11-09T17:52:30.784721+00:00","availableAt":"2026-11-10T17:52:30.784721+00:00","updatedAt":"2026-11-09T17:52:30.784721+00:00","lastUsedAt":"2026-11-09T17:52:28.602287+00:00"},"fourth":{"limitedAt":"2026-11-09T18:16:27.645979+00:00","availableAt":"2026-11-10T18:16:27.645979+00:00","updatedAt":"2026-11-09T18:16:27.645979+00:00","lastUsedAt":"2026-11-09T18:16:23.031938+00:00"},"fifth":{"limitedAt":"2026-11-08T16:07:14.000Z","availableAt":"2026-11-09T16:07:14.000Z","updatedAt":"2026-11-09T18:27:42.499423+00:00","lastUsedAt":"2026-11-09T18:27:42.499423+00:00"}},"variantFid":"3c43208bb81846468171485167009d47","notes":{"ru":{"top":["Бергамот","Лимон","Мандарин","Зелёные Ноты","Розовый Перец"],"heart":["Жасмин","Роза","Ландыш","Фрезия","Персик"],"base":["Белый Мускус","Кедровая Древесина","Амбра","Ветивер","Ваниль"]},"en":{"top":["Bergamot","Lemon","Mandarin Orange","Green Notes","Pink Pepper"],"heart":["Jasmine","Rose","Lily of the Valley","Freesia","Peach"],"base":["White Musk","Cedarwood","Amber","Vetiver","Vanilla"]}},"notesVerified":true,"notesSource":"deepseek","notesLookup":{"status":"found","source":"deepseek","checkedAt":"2026-11-11T20:46:20.731Z","model":"deepseek-chat","generated":true},"notesSummaryEn":"Bergamot · Lemon · Jasmine · White Musk","descriptionRu":"Dirham Eau de Parfum от Ard Al Zaafaran — это бодрящая и элегантная композиция, сочетающая искристую цитрусовую свежесть с утонченным цветочно-древесным характером. Этот аромат выстраивает гармоничный баланс между бодрящей легкостью и мягким, обволакивающим шлейфом. Верхние ноты открываются ярким аккордом бергамона, лимона и мандарина, дополненными зелеными нотами и деликатной остротой розового перца. Постепенно раскрываясь, композиция переходит в сердце, где звучит бархатистый букет из жасмина, розы, ландыша и фрезии, смягченный сочным акцентом персика. В базе аромат обретает глубину и теплоту благодаря сочетанию белого мускуса, кедра, янтаря, ветивера и ванили. Этот завершающий штрих оставляет на коже элегантное и сбалансированное послевкусие.","descriptionEn":"Dirham Eau de Parfum by Ard Al Zaafaran is an invigorating and elegant composition that blends sparkling citrus freshness with a refined floral-woody character. This fragrance builds a harmonious balance between uplifting lightness and a soft, enveloping trail. The fragrance opens with a vibrant burst of bergamot, lemon, and mandarin orange, accented by green notes and the delicate spice of pink pepper. As it evolves, the heart reveals a velvety bouquet of jasmine, rose, lily of the valley, and freesia, softened by a juicy touch of peach. In the base, the scent gains depth and warmth through a combination of white musk, cedarwood, amber, vetiver, and vanilla. This grounding finish leaves an elegant and well-rounded trace on the skin.","descriptionSource":"gemini","descriptionsLookup":{"source":"gemini","model":"gemini-3.5-flash-lite","checkedAt":"2026-11-13T20:41:07.889Z"}}'::json),
