  (5153, '2026-11-02T10:59:24.05111+00:00', 'Ajmal Boudoir Oud Allure Eau de Parfum for Men', '/assets/img/generated-products/2085c463c2879f92c1c40baa0276f6fd5eb540505463bad2d2daba58d08df3b4.png', 'Ajmal Boudoir Oud Allure Eau de Parfum for Men 3.4 fl oz — оригинальный премиальный парфюм бренда Ajmal.', 'Ajmal', 46.42, '{"gtin":"6293708020744","gender":"Мужской","volume":"100 мл EDP","sillage":"Заметный, шлейфовый","category":"Древесные","rawImage":"https://static.prod.qogita.com/files/images/variants/FMq253RJATZRWxyDqYZhD3.jpg","longevity":"10–14 часов","notesSummary":"Бергамот · Розовый Перец · Уд · Амбра","imageGeneration":{"status":"completed","attemptedOn":"2026-11-10","startedAt":"2026-11-10T17:26:21.367421+00:00","model":"@cf/black-forest-labs/flux-2-klein-4b","steps":4,"imageUrl":"/assets/img/generated-products/2085c463c2879f92c1c40baa0276f6fd5eb540505463bad2d2daba58d08df3b4.png","width":1024,"height":1024,"completedAt":"2026-11-10T17:34:23.148938+00:00"},"retiredGeneratedImages":["/assets/img/generated-products/fbefbe3c0bed0349f88bb85d26f86fec9ad641d7db76a125189ba7efa9fea264.png"],"imageGenerationAccountQuotas":{"primary":{"limitedAt":"2026-11-09T16:37:32.502406+00:00","availableAt":"2026-11-10T16:37:32.502406+00:00","updatedAt":"2026-11-10T17:26:27.463887+00:00","lastUsedAt":"2026-11-10T17:26:27.463887+00:00"},"secondary":{"limitedAt":"2026-11-09T17:25:40.999458+00:00","availableAt":"2026-11-10T17:25:40.999458+00:00","updatedAt":"2026-11-09T17:25:40.999458+00:00","lastUsedAt":"2026-11-09T17:25:38.252920+00:00"},"third":{"limitedAt":"2026-11-09T17:52:30.784721+00:00","availableAt":"2026-11-10T17:52:30.784721+00:00","updatedAt":"2026-11-09T17:52:30.784721+00:00","lastUsedAt":"2026-11-09T17:52:28.602287+00:00"},"fourth":{"limitedAt":"2026-11-09T18:16:27.645979+00:00","availableAt":"2026-11-10T18:16:27.645979+00:00","updatedAt":"2026-11-09T18:16:27.645979+00:00","lastUsedAt":"2026-11-09T18:16:23.031938+00:00"},"fifth":{"limitedAt":"2026-11-09T18:40:25.593266+00:00","availableAt":"2026-11-10T18:40:25.593266+00:00","updatedAt":"2026-11-09T18:40:25.593266+00:00","lastUsedAt":"2026-11-09T18:40:12.658233+00:00"}},"variantFid":"cf5523b4488a4047aefcad196f53a254","notes":{"ru":{"top":["Бергамот","Розовый Перец","Кардамон","Лаванда"],"heart":["Уд","Роза","Шафран","Кедр"],"base":["Амбра","Мускус","Сандал","Ваниль","Пачули"]},"en":{"top":["Bergamot","Pink Pepper","Cardamom","Lavender"],"heart":["Oud","Rose","Saffron","Cedar"],"base":["Amber","Musk","Sandalwood","Vanilla","Patchouli"]}},"notesVerified":true,"notesSource":"deepseek","notesLookup":{"status":"found","source":"deepseek","checkedAt":"2026-11-11T20:44:39.258Z","model":"deepseek-chat","generated":true},"notesSummaryEn":"Bergamot · Pink Pepper · Oud · Amber","descriptionRu":"Ajmal Boudoir Oud Allure — это глубокая древесная композиция, в которой холодная пряная острота встречается с обволакивающей восточной чувственностью. Аромат выстраивает сложный контраст между бодрящим вступлением и величественным, тягучим шлейфом. Начало раскрывается искристой свежестью бергамота, смягченной пряным теплом розового перца и кардамона, чью строгость уравновешивает травянистая чистота лаванды. Постепенно композиция обретает более плотный характер: в сердце доминируют насыщенный уд и бархатистая роза, дополненные благородством кедра и драгоценными оттенками шафрана. Завершающий аккорд окутывает мягкой теплотой амбры, сандала и ванили, оставляя на коже глубокий мускусный след с землистыми нюансами пачули. Этот многогранный финал придает аромату особую стойкость и уверенный, выдержанный характер.","descriptionEn":"Ajmal Boudoir Oud Allure is a profound woody composition where crisp, spicy sharpness meets enveloping oriental sensuality. The fragrance builds a sophisticated contrast between an invigorating opening and a majestic, lingering trail. The scent begins with the sparkling freshness of bergamot, softened by the spicy warmth of pink pepper and cardamom, while a touch of lavender adds an herbal clarity. As it evolves, the fragrance takes on a more substantial character; the heart centers on rich oud and velvety rose, complemented by the noble structure of cedar and the precious spice of saffron. The final accord envelops the senses in the warm embrace of amber, sandalwood, and vanilla, leaving a deep musky trail nuanced by earthy patchouli. This multi-layered finish lends the fragrance remarkable persistence and a confident, poised character.","descriptionSource":"gemini","descriptionsLookup":{"source":"gemini","model":"gemini-3.1-flash-lite","checkedAt":"2026-11-13T20:19:04.487Z"}}'::json),
